// Choisit l'outil dont la capacité répond au besoin de l'intention.
// TODO : renvoyer le PREMIER outil est faux — il faut trouver celui dont
//        la capability correspond à intent.need, et 'none' si aucun.
export function selectTool(intent, tools) {
  return tools[0] ? tools[0].id : 'none';
}

